import { export_audit_trail } from "@/graphql/mutations";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    DialogExportAuditTrail: Boolean,
    tableData: Array
  },
  data: () => ({
    filtered_app: "ALL",
    filtered_source: "0",
    startMenu: false,
    endMenu: false,
    isLoading: false,
    startDate: new Date(),
    endDate: new Date(),
    AppItems: [{
      title: "All",
      value: "ALL"
    }, {
      title: "Cabinet",
      value: "CABINET"
    }, {
      title: "Channel",
      value: "CHANNEL"
    }, {
      title: "Dashboard",
      value: "DASHBOARD"
    }, {
      title: "Directory",
      value: "DIRECTORY"
    }, {
      title: "Events",
      value: "EVENTS"
    }, {
      title: "Expense",
      value: "EXPENSE"
    }, {
      title: "Form",
      value: "FORM"
    }, {
      title: "Presence",
      value: "PRESENCE"
    }, {
      title: "Slot Booking",
      value: "SLOT_BOOKING"
    }, {
      title: "Stichh",
      value: "STICHH"
    }, {
      title: "Task",
      value: "TASK"
    }, {
      title: "Ticket Management",
      value: "TICKET_MANAGEMENT"
    }, {
      title: "Timesheet",
      value: "TIMESHEET"
    }, {
      title: "Workflow",
      value: "WORKFLOW"
    }],
    SourceItems: [{
      title: "All",
      value: "0"
    }, {
      title: "Web",
      value: "1"
    }, {
      title: "Phone",
      value: "2"
    }]
  }),
  watch: {
    startDate(newStartDate) {
      if (newStartDate && this.endDate && newStartDate > this.endDate) {
        this.endDate = new Date(newStartDate);
      }
    }
  },
  computed: {
    formatedStartDate() {
      if (!this.startDate) return "";
      return this.ConvertStartDate(this.startDate);
    },
    formatedEndDate() {
      if (!this.endDate) return "";
      return this.ConvertEndDate(this.endDate);
    }
  },
  methods: {
    ConvertStartDate(startDate) {
      const date = new Date(startDate);
      const yyyy = date.getFullYear();
      const mm = String(date.getMonth() + 1).padStart(2, "0");
      const dd = String(date.getDate()).padStart(2, "0");
      return `${yyyy}-${mm}-${dd}`;
    },
    ConvertEndDate(endDate) {
      const date = new Date(endDate);
      const yyyy = date.getFullYear();
      const mm = String(date.getMonth() + 1).padStart(2, "0");
      const dd = String(date.getDate()).padStart(2, "0");
      return `${yyyy}-${mm}-${dd}`;
    },
    async exportAuditTrail() {
      this.isLoading = true;
      try {
        let result = await API.graphql(graphqlOperation(export_audit_trail, {
          input: {
            limit: 100,
            organization_id: this.$store.getters.GetOrgDetails.organization.organization_id,
            audit_type: this.filtered_app,
            from_date: this.ConvertStartDate(this.startDate),
            to_date: this.ConvertEndDate(this.endDate),
            source: this.filtered_source
          }
        }));
        let response = JSON.parse(result.data.export_audit_trail);
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          window.open(response.URL);
          this.DialogExportAuditTrailEmit(2);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        console.log("Error", error);
        const errorMessage = error.errors && error.errors[0] ? error.errors[0].message : "Failed to export audit trails. Please try again.";
        this.$emit("errorMsg", errorMessage);
      } finally {
        this.isLoading = false;
      }
    },
    resetForm() {
      this.filtered_app = "ALL";
      this.filtered_source = "0";
      this.startDate = new Date();
      this.endDate = new Date();
      this.startMenu = false;
      this.endMenu = false;
    },
    DialogExportAuditTrailEmit(Toggle) {
      this.resetForm();
      this.$emit("clicked", Toggle);
    }
  }
};
